.wswebshot__kh .wswebshot__k{flex-direction:row;align-items:stretch}.wswebshot__kh .wswebshot__km{flex:0 0 42%}.wswebshot__kh .wswebshot__km img{height:100%;aspect-ratio:auto;min-height:260px}.wswebshot__kh .wswebshot__kt{padding:24px;display:flex;flex-direction:column;justify-content:center}
