.wswebshot__kicker{color:#164d9e;letter-spacing:1.8px;font-size:12.5px}.wswebshot__kicker::before{content:"";display:inline-block;width:22px;height:2px;background:#164d9e;vertical-align:middle;margin:-2px 10px 0 0;border-radius:2px}
