.wswebshot__red4:not(.wswebshot__pog)>div{background:#fff;border:1px solid rgba(22,77,158,.35);border-radius:16px;padding:24px 16px;box-shadow:0 6px 18px rgba(0,0,0,.05)}.wswebshot__red3 span.wswebshot__pi{width:44px;height:44px;margin-bottom:8px}.wswebshot__red3 .wswebshot__pi svg{width:22px;height:22px}.wswebshot__red3>div{border-color:rgba(22,77,158,.35)}
