div.wswebshot__pog{text-align:center;border:1px solid rgba(22,77,158,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wswebshot__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(22,77,158,.22)}div.wswebshot__pog>strong,div.wswebshot__pog>span:not(.wswebshot__pi){display:block}
